package com.example.employeeleave;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import org.springframework.web.server.ResponseStatusException; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate; import java.time.temporal.ChronoUnit; import java.util.*;
@RestController @RequestMapping("/api/leaves") public class LeaveController {
 private final LeaveRepository leaves; private final UserRepository users; private final LeaveTypeRepository types;
 public LeaveController(LeaveRepository l,UserRepository u,LeaveTypeRepository t){leaves=l;users=u;types=t;}
 @GetMapping public List<Map<String,Object>> all(org.springframework.security.core.Authentication auth){User actor=currentUser(auth);List<LeaveRequest> data=actor.getRole().equals("EMPLOYEE")?leaves.findByUserIdOrderByCreatedAtDesc(actor.getId()):leaves.findAll();return data.stream().map(this::view).toList();}
 @GetMapping("/user/{userId}") public List<Map<String,Object>> byUser(@PathVariable Long userId,org.springframework.security.core.Authentication auth){User actor=currentUser(auth);if(actor.getRole().equals("EMPLOYEE")&&!actor.getId().equals(userId))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only view your own leave requests");return leaves.findByUserIdOrderByCreatedAtDesc(userId).stream().map(this::view).toList();}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable Long id,org.springframework.security.core.Authentication auth){LeaveRequest l=leaves.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found"));User actor=currentUser(auth);if(actor.getRole().equals("EMPLOYEE")&&!actor.getId().equals(l.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only view your own leave request");return view(l);}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody LeaveBody b,org.springframework.security.core.Authentication auth){if(b.getEndDate().isBefore(b.getStartDate()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"End date must not be before start date");User actor=currentUser(auth);String type=b.getLeaveType();if((type==null||type.isBlank())&&b.getLeaveTypeId()!=null)type=types.findById(b.getLeaveTypeId()).map(LeaveType::getName).orElse(null);if(type==null||type.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Leave type is required");if(types.findByNameIgnoreCase(type).filter(LeaveType::isActive).isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Please select an active leave type");LeaveRequest l=new LeaveRequest();l.setUserId(actor.getId());l.setLeaveType(type);l.setStartDate(b.getStartDate());l.setEndDate(b.getEndDate());l.setReason(b.getReason());l.setStatus("PENDING");return ResponseEntity.status(HttpStatus.CREATED).body(view(leaves.save(l)));}
 @PatchMapping("/{id}/decision") public Map<String,Object> decide(@PathVariable Long id,@RequestBody DecisionBody b,org.springframework.security.core.Authentication auth){LeaveRequest l=leaves.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Leave request not found"));User actor=currentUser(auth);String status=b.getStatus().trim().toUpperCase();if(!List.of("APPROVED","REJECTED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status must be APPROVED, REJECTED or CANCELLED");if(!"PENDING".equalsIgnoreCase(l.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending requests can be changed");if("CANCELLED".equals(status)){if(!actor.getId().equals(l.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You can only cancel your own leave request");}else{if(!List.of("MANAGER","ADMIN").contains(actor.getRole()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Manager or admin role required");if(actor.getId().equals(l.getUserId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot approve or reject your own leave request");}l.setStatus(status);l.setReviewComment(b.getComment());return view(leaves.save(l));}
 private User currentUser(org.springframework.security.core.Authentication auth){return users.findByEmailIgnoreCase(auth.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"User account not found"));}
 private Map<String,Object> view(LeaveRequest l){User u=users.findById(l.getUserId()).orElse(null);long days=ChronoUnit.DAYS.between(l.getStartDate(),l.getEndDate())+1;Map<String,Object> m=new LinkedHashMap<>();m.put("id",l.getId());m.put("userId",l.getUserId());m.put("user",u==null?null:Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail()));m.put("employeeName",u==null?"Employee":u.getName());m.put("leaveType",l.getLeaveType());m.put("leaveTypeName",l.getLeaveType());m.put("startDate",l.getStartDate());m.put("endDate",l.getEndDate());m.put("totalDays",days);m.put("reason",l.getReason());m.put("status",l.getStatus());m.put("reviewComment",l.getReviewComment());m.put("createdAt",l.getCreatedAt());return m;}
 public static class LeaveBody {private Long userId;private Long leaveTypeId;private String leaveType;@NotNull private LocalDate startDate;@NotNull private LocalDate endDate;@NotBlank @Size(max=1000) private String reason;public Long getUserId(){return userId;}public Long getLeaveTypeId(){return leaveTypeId;}public String getLeaveType(){return leaveType;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public String getReason(){return reason;}public void setUserId(Long v){userId=v;}public void setLeaveTypeId(Long v){leaveTypeId=v;}public void setLeaveType(String v){leaveType=v;}public void setStartDate(LocalDate v){startDate=v;}public void setEndDate(LocalDate v){endDate=v;}public void setReason(String v){reason=v;}}
 public static class DecisionBody {private String status;private String comment;public String getStatus(){return status==null?"":status;}public String getComment(){return comment;}public void setStatus(String v){status=v;}public void setComment(String v){comment=v;}}
}
